using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Text;
using System.Web.Script.Serialization;
using System.Collections.Generic;

// Output lifecycle only. No model/geometry changes. Each record is durable before work starts.
public static class JobOwnership {
 public static string Context {get{return Environment.GetEnvironmentVariable("SOLIDWORKSBREP_RUN_CONTEXT");}}
 static JavaScriptSerializer J=new JavaScriptSerializer();
 public static void Record(object value){string root=Context;if(String.IsNullOrEmpty(root))return;Directory.CreateDirectory(Path.Combine(root,"ownership"));string target=Path.Combine(root,"ownership",Guid.NewGuid().ToString("N")+".json"),tmp=target+".tmp";File.WriteAllText(tmp,J.Serialize(value),new UTF8Encoding(false));File.Move(tmp,target);}
 public static void Session(int pid){if(String.IsNullOrEmpty(Context))return;using(var p=Process.GetProcessById(pid)){string path=Path.Combine(Context,"solidworks.json");string data=J.Serialize(new{pid,start=p.StartTime.ToUniversalTime().Ticks});if(File.Exists(path)){if(File.ReadAllText(path)!=data)throw new Exception("Job attempted to switch SolidWorks process");return;}File.WriteAllText(path,data);}}
 public static void OwnDirectory(string path,string project){if(String.IsNullOrEmpty(Context)) {Directory.CreateDirectory(path);return;}path=Path.GetFullPath(path);project=Path.GetFullPath(project);Validate(path,project);if(Directory.Exists(path)&&Directory.EnumerateFileSystemEntries(path).Any())throw new Exception("Cannot own a nonempty output directory: "+path);Record(new{kind="directory",path,project});Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,".swbrep-run-owner"),Path.GetFileName(Context));}
 public static void BackupPackage(string path,string project,string role){if(String.IsNullOrEmpty(Context))return;Validate(path,project);Record(new{kind="package",path=Path.GetFullPath(path),project=Path.GetFullPath(project),role,existed=File.Exists(path),data=File.Exists(path)?Convert.ToBase64String(File.ReadAllBytes(path)):null});}
 public static void BackupFile(string path,string project){if(String.IsNullOrEmpty(Context))return;Validate(path,project);Record(new{kind="file",path=Path.GetFullPath(path),project=Path.GetFullPath(project),existed=File.Exists(path),data=File.Exists(path)?Convert.ToBase64String(File.ReadAllBytes(path)):null});}
 public static void Validate(string path,string project){path=Path.GetFullPath(path);project=Path.GetFullPath(project).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!path.StartsWith(project,StringComparison.OrdinalIgnoreCase))throw new Exception("Cleanup target is outside project");string p=path;while(!String.IsNullOrEmpty(p)){if((Directory.Exists(p)||File.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new Exception("Reparse path cannot be cleaned: "+p);p=Path.GetDirectoryName(p);}}
 static void NoLinks(string root){foreach(string p in Directory.GetFileSystemEntries(root)){if((File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new Exception("Reparse entry cannot be cleaned: "+p);if(Directory.Exists(p))NoLinks(p);}}
 public static void Cleanup(string context){string records=Path.Combine(context,"ownership");if(!Directory.Exists(records))return;var projects=Directory.GetFiles(records,"*.json").Select(p=>J.Deserialize<Dictionary<string,object>>(File.ReadAllText(p))).Select(e=>(string)e["project"]).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(p=>p,StringComparer.OrdinalIgnoreCase);var locks=new List<FileStream>();try{foreach(string project in projects){string temp=Path.Combine(project,new DirectoryInfo(project).Name+"_temp");Validate(temp,project);Directory.CreateDirectory(temp);locks.Add(new FileStream(Path.Combine(temp,"layout.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None));}CleanupLocked(context);}finally{foreach(var guard in locks)guard.Dispose();}}
 static void CleanupLocked(string context){string records=Path.Combine(context,"ownership");if(!Directory.Exists(records))return;var entries=Directory.GetFiles(records,"*.json").Select(p=>J.Deserialize<Dictionary<string,object>>(File.ReadAllText(p))).ToArray();
  foreach(var entry in entries.Where(e=>(string)e["kind"]=="directory").OrderByDescending(e=>((string)e["path"]).Length)){string path=(string)entry["path"];Validate(path,(string)entry["project"]);if(!Directory.Exists(path))continue;string marker=Path.Combine(path,".swbrep-run-owner");if(!File.Exists(marker)||File.ReadAllText(marker)!=Path.GetFileName(context))throw new Exception("Output ownership is not confirmed: "+path);NoLinks(path);Directory.Delete(path,true);}
  foreach(var entry in entries.Where(e=>(string)e["kind"]!="directory")){string path=(string)entry["path"];string done=Path.Combine(context,"restored-"+BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(path))).Replace("-","")+".txt");if(File.Exists(done))continue;Validate(path,(string)entry["project"]);if((string)entry["kind"]=="package"&&File.Exists(path)){var current=J.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));var before=J.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(Convert.FromBase64String((string)entry["data"])).TrimStart('\ufeff'));var roles=(Dictionary<string,object>)current["roles"];var oldRoles=(Dictionary<string,object>)before["roles"];string role=(string)entry["role"];if(oldRoles.ContainsKey(role))roles[role]=oldRoles[role];else roles.Remove(role);File.WriteAllText(path,J.Serialize(current),new UTF8Encoding(false));}else if((bool)entry["existed"])File.WriteAllBytes(path,Convert.FromBase64String((string)entry["data"]));else if(File.Exists(path))File.Delete(path);File.WriteAllText(done,"restored");}
 }
 public static void Commit(string context){string records=Path.Combine(context,"ownership");if(!Directory.Exists(records))return;foreach(string record in Directory.GetFiles(records,"*.json")){var e=J.Deserialize<Dictionary<string,object>>(File.ReadAllText(record));if((string)e["kind"]!="directory")continue;string marker=Path.Combine((string)e["path"],".swbrep-run-owner");if(File.Exists(marker)&&File.ReadAllText(marker)==Path.GetFileName(context))File.Delete(marker);}}
}
